      const cards = IV.quick.flatMap(([k, v], i) => { const x = M + (i % 3) * (cw + 14), y = 128 + Math.floor(i / 3) * (ch + 14); return [rect(x, y, cw, ch, i % 2 ? mix(paper, -.05) : mix(secondary, .72), { label: 'Quick-fire card', role: 'SIDEBAR' }), rect(x, y, 4, ch, i % 2 ? accent : gold, { label: 'Card edge', role: 'RULE' }), label(x + 16, y + 12, cw - 28, k, { size: 7.5, font: 'dmSans', color: soft, weight: 700, tracking: .16, wrap: true, role: 'SIDEBAR', label: 'Quick-fire question' }), text(x + 16, y + 34, cw - 28, v, { size: 14, font: 'ebGaramond', italic: true, color: ink, leading: 1.25, role: 'SIDEBAR', label: 'Quick-fire answer' })]; });
      const title = obj(label(M, 96, 300, 'Quick-fire round', { size: 9, font: 'dmSans', color: accent, weight: 800, tracking: .22, role: 'SIDEBAR' }), hr(M, 114, W - 2 * M, ink, 1.25));
      return obj(G, head(3), title, cards, pages[2].objs, ...note(NX, 420, NW, 'she hums when she thinks. you can hear it on the tape', -2), ...note(NX, 700, NW, 'cut? no. keep the lichens.', 3), foot());
