      const player = obj(rect(M, 330, W - 2 * M, 84, mix(paper, -.05), { rx: 8, label: 'Audio player', role: 'SIDEBAR' }), circle(M + 44, 372, 24, accent, { label: 'Play button' }), path(M + 37, 360, 20, 24, 'M20 0 L100 50 L20 100 Z', paper, { label: 'Play icon' }), wf, text(W - M - 110, 392, 96, '10:42 / 48:12', { size: 10, font: 'dmMono', color: soft, wrap: false, align: 'right', label: 'Timecode', role: 'CAPTION' }), label(M + 96, 338, 300, 'Listen to the full conversation', { size: 8, font: 'dmSans', color: accent, weight: 800, tracking: .16, role: 'SIDEBAR' }));
      const aboutX = M, aboutW = 330;
      const about = obj(hr(M, 452, aboutW, ink, 1.25), label(M, 462, aboutW, 'About Marisol Quint', { size: 8.5, font: 'dmSans', color: accent, weight: 800, tracking: .22 }), text(M, 484, aboutW, 'Marisol Quint has written for more than two hundred community choirs. Her song cycle Small Weather has been recorded eleven times. She teaches at the Leith Conservatoire and lives with a cello she describes as “a very tall lodger.”', { size: 14, font: 'ebGaramond', color: ink, leading: 1.5, label: 'Subject biography', role: 'SIDEBAR' }));
      const cr = table(M + aboutW + 40, 462, [{ w: 110, font: 'dmSans', size: 8, weight: 700, color: soft, tracking: .12 }, { w: W - 2 * M - aboutW - 40 - 110, font: 'dmSerif', size: 13 }], [['Interview', 'Teo Brandt'], ['Photographs', 'Ada Njoku'], ['Transcription', 'Lena Okafor'], ['Edited by', 'Priya Natarajan'], ['Recorded', '12 September 2026']], { size: 12, font: 'dmSans', color: ink, rule: hair, pad: 7, head: ['Credits', ''], headSize: 8, headColor: accent, headRule: ink, label: 'Credits' });
      const next = obj(rect(M, 750, W - 2 * M, 200, ink, { label: 'Next card', role: 'SIDEBAR' }), ...imageSlot(M, 750, 250, 200, { tone: 'dark', shade: mix(ink, .15), caption: 'Next portrait', label: 'Next portrait' }), label(M + 280, 780, 300, 'Next in conversation', { size: 8.5, font: 'dmSans', color: gold, weight: 800, tracking: .22, role: 'SIDEBAR' }), text(M + 280, 804, 400, '“I built the shop around the one chair that wobbles.”', { size: 28, font: 'dmSerif', color: paper, leading: 1.12, label: 'Next headline', role: 'HEADLINE' }), text(M + 280, 900, 400, 'The furniture maker Anselm Ode on repair, regret and the sound of a plane.', { size: 13, font: 'ebGaramond', italic: true, color: alpha(paper, .8), leading: 1.4, role: 'SIDEBAR', label: 'Next deck' }));
